async function traceTransactionExecution(transactionName, execute) {
  const requestId = getCurrentRequestId();
  const context = getRequestContext();
  const startHr = process.hrtime.bigint();
  safeLogger.info(`[Firestore Core] \u{1F7E2} Transaction [${transactionName}] initiated`, {
    transaction: transactionName,
    requestId,
    route: context?.path
  });
  try {
    const result = await execute();
    const endHr = process.hrtime.bigint();
    const durationMs = Number((Number(endHr - startHr) / 1e6).toFixed(2));
    safeLogger.info(
      `[Firestore Core] \u{1F7E2} Transaction [${transactionName}] committed (${durationMs}ms)`,
      {
        transaction: transactionName,
        requestId,
        durationMs,
        success: true
      }
    );
    recordTransactionMetric({
      name: transactionName,
      durationMs,
      success: true,
      timestamp: (/* @__PURE__ */ new Date()).toISOString(),
      requestId: requestId || "unknown"
    });
    return result;
  } catch (err) {
    const endHr = process.hrtime.bigint();
    const durationMs = Number((Number(endHr - startHr) / 1e6).toFixed(2));
    const errorMsg = err instanceof Error ? err.message : String(err);
    safeLogger.error(
      `[Firestore Core] \u274C Transaction [${transactionName}] failed/rolled back (${durationMs}ms)`,
      {
        transaction: transactionName,
        requestId,
        durationMs,
        error: errorMsg,
        success: false
      }
    );
    recordTransactionMetric({
      name: transactionName,
      durationMs,
      success: false,
      timestamp: (/* @__PURE__ */ new Date()).toISOString(),
      requestId: requestId || "unknown"
    });
    throw err;
  }
}

