    const userSnap = await userRef.get();
    if (!userSnap.exists) {
      throw new Error("Vendeur non trouv\xE9");
    }
    const userData = userSnap.data() || {};
    await userRef.update({
      role: "seller",
      status: "active",
      isVerified: true,
      sellerTrustScore: 90,
      approvedAt: import_firebase_admin.default.firestore.FieldValue.serverTimestamp()
    });
