router13.post("/admin/send-newsletter", authenticateToken, authorizeAdmin, async (req, res) => {
  try {
    const { subject, content, targetAudience } = req.body;
    if (!subject || !content) {
      return res.status(400).json({ error: "Sujet et contenu requis" });
    }
    let subscribersQuery = db.collection("newsletter_subscribers").where("active", "==", true);
    if (targetAudience && targetAudience !== "all") {
      subscribersQuery = subscribersQuery.where("segment", "==", targetAudience);
    }
    const snap = await subscribersQuery.get();
    const emails = snap.docs.map((doc) => doc.data().email).filter(Boolean);
    if (emails.length === 0) {
      return res.status(400).json({ error: "Aucun abonn\xE9 trouv\xE9 pour ce segment" });
    }
    const batchSize = 100;
    for (let i = 0; i < emails.length; i += batchSize) {
      const chunk = emails.slice(i, i + batchSize);
      const mailPromises = chunk.map(
        (email) => db.collection("mail").add({
          to: email,
          message: {
            subject,
            html: content
          }
        })
      );
      await Promise.all(mailPromises);
    }
    await db.collection("newsletter_campaigns").add({
      subject,
      targetAudience: targetAudience || "all",
      recipientCount: emails.length,
      sentAt: import_firebase_admin.default.firestore.FieldValue.serverTimestamp(),
      sentBy: req.user?.uid || "admin"
    });
    await db.collection("audit_logs").add({
      type: "MARKETING",
      action: "NEWSLETTER_SENT",
      adminId: req.user?.uid || "admin",
      details: { subject, recipientCount: emails.length },
      timestamp: import_firebase_admin.default.firestore.FieldValue.serverTimestamp()
    });
    res.json({ success: true, count: emails.length });
  } catch (err) {
    res.status(500).json({ error: err instanceof Error ? err.message : "Erreur interne" });
  }
});
