router17.post("/admin/users/bulk-delete", authenticateToken, authorizeAdmin, async (req, res) => {
  try {
    const { userIds } = req.body;
    if (!Array.isArray(userIds) || userIds.length === 0) {
      return res.status(400).json({ error: "Liste d'utilisateurs requise" });
    }
    if (userIds.length > 20) {
      return res.status(400).json({ error: "La suppression en masse est limit\xE9e \xE0 20 utilisateurs maximum par op\xE9ration." });
    }
    const batchSize = 400;
    for (let i = 0; i < userIds.length; i += batchSize) {
      const chunk = userIds.slice(i, i + batchSize);
      const batch = db.batch();
      chunk.forEach((uid) => {
        const ref = db.collection("users").doc(uid);
        batch.delete(ref);
      });
      await batch.commit();
    }
    await Promise.allSettled(
      userIds.map(
        (uid) => import_firebase_admin.default.auth().revokeRefreshTokens(uid).catch((authErr) => {
          safeLogger.warn("Failed to revoke refresh tokens on bulk user deletion", {
            uid,
            err: authErr instanceof Error ? authErr.message : String(authErr)
          });
        })
      )
    );
    await db.collection("audit_logs").add({
      type: "USER_MANAGEMENT",
      action: "BULK_DELETE_USERS",
      targetUserIds: userIds,
      adminId: req.user?.uid || "admin",
      details: { count: userIds.length },
      timestamp: import_firebase_admin.default.firestore.FieldValue.serverTimestamp()
    });
    res.json({ success: true, count: userIds.length });
  } catch (error) {
    res.status(500).json({ error: error instanceof Error ? error.message : "Erreur interne" });
  }
});
router17.delete("/admin/users/:id", authenticateToken, authorizeAdmin, async (req, res) => {
  try {
    const targetUserId = req.params.id;
    const callerId = req.user?.uid;
    const callerRole = req.user?.role || "admin";
    if (callerId && callerId === targetUserId) {
      return res.status(400).json({ error: "Action interdite : vous ne pouvez pas supprimer votre propre compte." });
    }
    const targetDoc = await db.collection("users").doc(targetUserId).get();
    if (!targetDoc.exists) {
      return res.status(404).json({ error: "Utilisateur introuvable." });
    }
    const targetData = targetDoc.data();
    const targetRole = targetData?.role || "buyer";
    const ROLE_WEIGHT = {
      buyer: 1,
      seller: 1,
      artisan: 1,
      property_owner: 1,
      admin: 2,
      superadmin: 3
    };
    const callerWeight = ROLE_WEIGHT[callerRole] || 1;
    const targetWeight = ROLE_WEIGHT[targetRole] || 1;
    if (targetWeight >= callerWeight && callerRole !== "superadmin") {
      return res.status(403).json({
        error: "Action interdite : vous n'avez pas l'autorisation d'agir sur un r\xF4le sup\xE9rieur ou \xE9quivalent."
      });
    }
    if (targetRole === "superadmin" && callerRole === "superadmin") {
      return res.status(403).json({
        error: "Action interdite : impossible de supprimer un superadministrateur."
      });
    }
    try {
      await import_firebase_admin.default.auth().deleteUser(targetUserId);
    } catch (authErr) {
      safeLogger.warn("Failed or skipped Firebase Auth deleteUser (attempting disable fallback)", {
        targetUserId,
        err: authErr instanceof Error ? authErr.message : String(authErr)
      });
      try {
        await import_firebase_admin.default.auth().updateUser(targetUserId, { disabled: true });
        await import_firebase_admin.default.auth().revokeRefreshTokens(targetUserId);
      } catch {
      }
    }
    await db.collection("users").doc(targetUserId).delete();
    clearUserProfileCache(targetUserId);
    try {
      await import_firebase_admin.default.auth().revokeRefreshTokens(targetUserId);
    } catch {
    }
    await db.collection("audit_logs").add({
      type: "USER_MANAGEMENT",
      action: "DELETE_USER",
      targetUserId,
      targetRole,
      adminId: callerId || "admin",
      timestamp: import_firebase_admin.default.firestore.FieldValue.serverTimestamp()
    });
    res.json({ success: true, message: "Utilisateur supprim\xE9 avec succ\xE8s." });
  } catch (error) {
    res.status(500).json({ error: error instanceof Error ? error.message : "Erreur interne" });
  }
});
