var SPONSORED_DAILY_RATES = {
  home: 800,
  category: 500,
  search: 400
};
var SPONSORED_RULES = {
  MIN_DAYS: 1,
  MAX_DAYS: 30,
  CURRENCY: "DZD"
};
function calculateCampaignPrice(placement, startAtStr, endAtStr) {
  if (!SPONSORED_DAILY_RATES[placement]) {
    return { valid: false, error: "Emplacement de sponsorisation invalide." };
  }
  const startDate = new Date(startAtStr);
  const endDate = new Date(endAtStr);
  if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) {
    return { valid: false, error: "Les dates fournies sont invalides." };
  }
  const diffMs = endDate.getTime() - startDate.getTime();
  if (diffMs <= 0) {
    return { valid: false, error: "La date de fin doit \xEAtre strictement post\xE9rieure \xE0 la date de d\xE9but." };
  }
  const durationDays = Math.ceil(diffMs / (1e3 * 60 * 60 * 24));
  if (durationDays < SPONSORED_RULES.MIN_DAYS) {
    return { valid: false, error: `La dur\xE9e minimale est de ${SPONSORED_RULES.MIN_DAYS} jour(s).` };
  }
  if (durationDays > SPONSORED_RULES.MAX_DAYS) {
    return { valid: false, error: `La dur\xE9e maximale autoris\xE9e pour une campagne est de ${SPONSORED_RULES.MAX_DAYS} jours.` };
  }
  const dailyRate = SPONSORED_DAILY_RATES[placement];
  const priceAmount = durationDays * dailyRate;
  return {
    valid: true,
    data: {
      durationDays,
      priceAmount,
      currency: SPONSORED_RULES.CURRENCY,
      dailyRate
    }
  };
}

