// src/domains/support/utils/supportValidation.ts
function validateSecureFilePath(filePath, ticketId, attachmentId) {
  if (!filePath) return false;
  const expectedPrefix = `support/${ticketId}/${attachmentId}/`;
  if (!filePath.startsWith(expectedPrefix)) return false;
  if (filePath.includes("..") || filePath.includes("\\") || filePath.startsWith("/") || /* eslint-disable-next-line no-control-regex */
  /[\x00-\x1F\x7F]/.test(filePath)) {
    return false;
  }
  return true;
}

