router49.post("/admin/:id/resolve", authenticateToken, authorizeAdmin, async (req, res) => {
  const disputeId = req.params.id;
  const { resolution, note } = req.body;
  if (!["buyer_refunded", "seller_paid", "split"].includes(resolution)) {
    return res.status(400).json({ error: "R\xE9solution invalide." });
  }
  try {
    await db.runTransaction(async (t) => {
      const disputeRef = db.collection("disputes").doc(disputeId);
      const disputeSnap = await t.get(disputeRef);
      if (!disputeSnap.exists) throw new Error("Litige introuvable.");
      const dispute = disputeSnap.data() || {};
      if (dispute.status === "resolved" || dispute.status === "closed") {
        throw new Error("Ce litige est d\xE9j\xE0 r\xE9solu.");
      }
      const orderRef = db.collection("orders").doc(dispute.orderId);
      const orderSnap = await t.get(orderRef);
      t.update(disputeRef, {
        status: "resolved",
        resolution,
        resolvedAt: import_firebase_admin.default.firestore.FieldValue.serverTimestamp(),
        updatedAt: import_firebase_admin.default.firestore.FieldValue.serverTimestamp(),
        adminNote: note || ""
      });
      let newOrderStatus = orderSnap.exists ? orderSnap.data()?.status : "dispute_open";
      if (resolution === "buyer_refunded") newOrderStatus = "refunded";
      if (resolution === "seller_paid") newOrderStatus = "delivered";
      if (orderSnap.exists) {
        t.update(orderRef, {
          status: newOrderStatus,
          updatedAt: import_firebase_admin.default.firestore.FieldValue.serverTimestamp()
        });
      }
      const financeTaskRef = db.collection("finance_tasks").doc();
      t.set(financeTaskRef, {
        type: "DISPUTE_RESOLUTION",
        disputeId,
        orderId: dispute.orderId,
        resolution,
        sellerId: dispute.sellerId,
        buyerId: dispute.buyerId,
        frozenAmount: dispute.frozenAmount,
        status: "pending",
        createdAt: import_firebase_admin.default.firestore.FieldValue.serverTimestamp()
      });
      const msgRef = db.collection("disputeMessages").doc();
      t.set(msgRef, {
        disputeId,
        senderId: "system",
        senderRole: "admin",
        message: `L'administrateur a r\xE9solu le litige : ${resolution === "buyer_refunded" ? "Remboursement de l'Acheteur" : "Paiement du Vendeur"}. Note: ${note || "Aucune note."}`,
        createdAt: import_firebase_admin.default.firestore.FieldValue.serverTimestamp()
      });
    });
    res.json({ success: true, message: "Litige r\xE9solu avec succ\xE8s. T\xE2che financi\xE8re asynchrone cr\xE9\xE9e." });
  } catch (error) {
    safeLogger.error("Error resolving dispute", { disputeId, err: error instanceof Error ? error.message : String(error) });
    res.status(500).json({ error: error instanceof Error ? error.message : "Erreur serveur" });
  }
});
router49.post("/:id/upload", authenticateToken, async (req, res) => {
  try {
    if (!req.user?.uid) {
      return res.status(401).json({ error: "Authentification requise" });
    }
    const disputeId = req.params.id;
    const userId = req.user.uid;
    const disputeRef = db.collection("disputes").doc(disputeId);
    const disputeDoc = await disputeRef.get();
    if (!disputeDoc.exists) {
      return res.status(404).json({ error: "Litige introuvable." });
    }
    const disputeData = disputeDoc.data() || {};
    const isAdmin = req.user.role === "admin" || req.user.role === "superadmin" || req.user.customClaims?.admin === true;
    const isBuyer = disputeData.buyerId === userId;
    const isSeller = disputeData.sellerId === userId;
    if (!isAdmin && !isBuyer && !isSeller) {
      return res.status(403).json({ error: "Acc\xE8s refus\xE9. Vous n'\xEAtes pas autoris\xE9 \xE0 uploader pour ce litige." });
    }
    const { fileName, mimeType, base64Data } = req.body;
    if (!fileName || !mimeType) {
      return res.status(400).json({ error: "Champs requis manquants: fileName, mimeType" });
    }
    const MAX_DISPUTE_ATTACHMENT_BYTES = 1048576;
    if (typeof base64Data !== "string") {
      return res.status(400).json({ error: "base64Data doit \xEAtre une cha\xEEne de caract\xE8res." });
    }
    if (!base64Data || base64Data.trim() === "") {
      return res.status(400).json({ error: "base64Data ne peut pas \xEAtre vide." });
    }
    const maxBase64Length = Math.ceil(MAX_DISPUTE_ATTACHMENT_BYTES * 4 / 3) + 4;
    if (base64Data.length > maxBase64Length) {
      return res.status(400).json({ error: "La taille estim\xE9e du fichier d\xE9passe la limite autoris\xE9e de 1 Mo." });
    }
    const cleanBase64 = base64Data.replace(/\s/g, "");
    const base64Regex = /^[a-zA-Z0-9+/]*={0,2}$/;
    if (!base64Regex.test(cleanBase64)) {
      return res.status(400).json({ error: "Format Base64 invalide." });
    }
    const buffer = Buffer.from(cleanBase64, "base64");
    if (buffer.length === 0) {
      return res.status(400).json({ error: "Le fichier d\xE9cod\xE9 est vide." });
    }
    if (buffer.length > MAX_DISPUTE_ATTACHMENT_BYTES) {
      return res.status(400).json({ error: "La taille r\xE9elle du fichier d\xE9passe la limite autoris\xE9e de 1 Mo." });
    }
    const allowedMimeTypes = [
      "image/jpeg",
      "image/png",
      "image/gif",
      "image/webp",
      "application/pdf",
      "application/zip",
      "text/plain",
      "text/csv"
    ];
    if (!allowedMimeTypes.includes(mimeType)) {
      return res.status(400).json({ error: "Type de fichier non support\xE9. Seuls les images, PDF, CSV, TXT et ZIP sont accept\xE9s." });
    }
    const validation = validateFileContent(buffer, fileName, mimeType);
    if (!validation.isValid) {
      return res.status(400).json({ error: validation.error || "Le contenu du fichier ne correspond pas au format d\xE9clar\xE9." });
    }
    const sanitizedName = fileName.replace(/[^a-zA-Z0-9.-]/g, "_");
    const attachRef = db.collection("disputeAttachments").doc();
    const attachmentId = attachRef.id;
    const uniquePath = `disputes/${disputeId}/${attachmentId}/${sanitizedName}`;
    const bucketName = process.env.VITE_FIREBASE_STORAGE_BUCKET || process.env.FIREBASE_STORAGE_BUCKET;
    const bucket = bucketName ? import_firebase_admin.default.storage().bucket(bucketName) : import_firebase_admin.default.storage().bucket();
    const fileUpload = bucket.file(uniquePath);
    let uploadedFile = false;
    try {
      await fileUpload.save(buffer, {
        metadata: { contentType: mimeType }
      });
      uploadedFile = true;
      await attachRef.set({
        disputeId,
        userId,
        fileName: sanitizedName,
        fileType: mimeType,
        filePath: uniquePath,
        fileSize: buffer.length,
        createdAt: import_firebase_admin.default.firestore.FieldValue.serverTimestamp()
      });
    } catch (writeError) {
      if (uploadedFile) {
        try {
          await fileUpload.delete();
        } catch (cleanupError) {
          safeLogger.error("Dispute Storage cleanup failed", { err: cleanupError instanceof Error ? cleanupError.message : String(cleanupError) });
        }
      }
      throw writeError;
    }
    const fileUrl = `/api/v1/disputes/${disputeId}/attachments/${attachmentId}`;
    await db.collection("adminActions").add({
      action: "dispute-file-upload",
      uid: userId,
      email: req.user.email || "inconnu",
      disputeId,
      attachmentId,
      fileName: sanitizedName,
      fileSize: buffer.length,
      timestamp: import_firebase_admin.default.firestore.FieldValue.serverTimestamp(),
      status: "success"
    });
    safeLogger.info("[Firestore Core] \u{1F7E2} Dispute file uploaded securely", { path: uniquePath, bytes: buffer.length });
    return res.json({
      success: true,
      attachmentId,
      fileUrl,
      fileName: sanitizedName,
      fileType: mimeType,
      fileSize: buffer.length
    });
  } catch (error) {
    safeLogger.error("[Firestore Core] \u274C Dispute upload error", { err: error instanceof Error ? error.message : String(error) });
    return res.status(500).json({ error: "Erreur serveur lors de l'upload de la pi\xE8ce jointe." });
  }
});
