var FALLBACK_WILAYAS = ALGERIA_WILAYAS.map((w, index) => {
  const parts = w.split(" ");
  const id = parseInt(parts[0] || "", 10) || index + 1;
  const name = parts.slice(1).join(" ");
  return { id, name, zone: 1 };
});
var getShippingLocations = async (req, res) => {
  try {
    return res.json({
      success: true,
      data: {
        wilayas: FALLBACK_WILAYAS,
        communes: [],
        centers: []
      }
    });
  } catch (error) {
    safeLogger.error("[Olmart Gateway] \u274C Error fetching shipping locations", { err: error instanceof Error ? error.message : String(error) });
    res.json({
      success: true,
      data: {
        wilayas: FALLBACK_WILAYAS,
        communes: [],
        centers: []
      }
    });
  }
};
var calculateShippingRates = async (req, res) => {
  try {
    const { wilaya_name } = req.body;
    let wilayaKey = "Default";
    if (wilaya_name) {
      const match = ALGERIA_WILAYAS.find((w) => w.toLowerCase().includes(String(wilaya_name).toLowerCase()));
      if (match) {
        wilayaKey = match.replace(/^[0-9]+\s*/, "");
      }
    }
    const shippingInfo = ALGERIA_SHIPPING_DATA[wilayaKey] || ALGERIA_SHIPPING_DATA.Default;
    const directFee = shippingInfo.price || 600;
    return res.json({
      success: true,
      data: {
        home_fee: directFee,
        desk_fee: Math.max(300, directFee - 200),
        delay: shippingInfo.delay || "24-48h (Livraison Directe Vendeur)"
      }
    });
  } catch (error) {
    safeLogger.error("[Olmart Gateway] \u274C Error calculating shipping rates", { err: error instanceof Error ? error.message : String(error) });
    res.json({
      success: true,
      data: {
        home_fee: 600,
        desk_fee: 400,
        delay: "24-48h (Livraison Directe Vendeur)"
      }
    });
  }
};

