      const parsed = createAutoPartSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: "Donn\xE9es de pi\xE8ce invalides", details: parsed.error.format() });
      }
      const sellerName = req.user.email?.split("@")[0] || "Vendeur Olma";
